"""
Exceptions for the Compute service.

"""

from qbraid_core.exceptions import HttpStatusMixin, QbraidException


class ComputeServiceRequestError(HttpStatusMixin, QbraidException):
    """Exception raised when a compute service API request fails."""


class ComputeProfileNotFoundError(HttpStatusMixin, QbraidException):
    """Exception raised when a profile is not found."""


class ComputeBuildError(HttpStatusMixin, QbraidException):
    """Exception raised when a profile build fails."""


class ComputeInsufficientTierError(HttpStatusMixin, QbraidException):
    """Exception raised when user's plan is below required tier."""


class ComputePermissionError(HttpStatusMixin, QbraidException):
    """Exception raised when user doesn't have permission (not owner, etc)."""


class ComputePaymentRequiredError(HttpStatusMixin, QbraidException):
    """Exception raised when payment is required (e.g., outstanding balance)."""
